from pathlib import Path
import csv,hashlib,html,json,re,subprocess
ROOT=Path(__file__).resolve().parent;REPO=ROOT.parents[2]
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def write(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
original=read(ROOT/'original_alpha/review_v1/inventory.json')
generated=[]
for p in sorted((ROOT/'review').glob('*/*.png')):
    if p.name.endswith('.alpha.png'):continue
    m=re.match(r'([0-9]{3})_',p.name)
    n=m.group(1) if m else {'PROJECT':'013','IXTAL':'014','BANDLE_CITY':'015'}.get(p.parent.name)
    if not n:raise ValueError(str(p))
    generated.append(dict(number=n,file=p.relative_to(REPO).as_posix(),sha256=sha(p),bytes=p.stat().st_size,status='review_user_selection_pending',kind='AI reconstruction or prior hybrid reconstruction; not original-pixel cutout'))
assert set(x['number'] for x in generated)=={f'{i:03}' for i in range(1,90)}
write(ROOT/'GENERATED_REVIEW_INDEX_V1.json',dict(source_coverage=89,files=len(generated),coverage_note='At least one reconstruction per source; not every subdesign/row regenerated',assets=generated,final_approved_count=0))
specs=read(ROOT/'effect_specs/review_v1/animation_catalog.json')['specs']
rows=[]
for source in original['sources']:
    n=source['number'];o=[a for a in original['assets'] if a['source_number']==n];g=[a for a in generated if a['number']==n]
    rows.append(dict(number=n,source=source['source'],preview=f'reference_previews/{n}.jpg',original=[a['file'].split('kill_frames_chatgpt/')[1] for a in o],generated=[a['file'].split('kill_frames_chatgpt/')[1] for a in g],quality_flags=sorted(set(str(flag) for a in o for flag in a['quality_flags']))))
page='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AutoCine 素材選別</title><style>body{font:16px system-ui;background:#171a21;color:#eef;margin:24px}header{position:sticky;top:0;background:#171a21;padding:12px;z-index:1}article{border:1px solid #586174;border-radius:10px;padding:18px;margin:18px 0}section{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}img{display:block;max-width:100%;max-height:240px;object-fit:contain;margin:auto}.image{background:repeating-conic-gradient(#ddd 0% 25%,#fff 0% 50%) 50% / 20px 20px;padding:14px;border-radius:6px;color:#222}.image.dark{background:#111}.image.white{background:#fff}button,select,input{font:inherit;padding:8px;margin:4px}a{color:#8ed9ff}small{display:block;overflow-wrap:anywhere}p{line-height:1.6}details{margin:10px 0}</style><header><b>AutoCine 素材選別</b><p>生成版／原本透過版を別々に選別。全てreview・自動合格なし。下の記録はこのブラウザ内に保存されます。</p><input id="search" placeholder="番号・原本名で検索"><button id="export">判断をJSON保存</button><select id="bg"><option value="">チェック</option><option value="dark">黒</option><option value="white">白</option></select></header><main id="list"></main><script>const data=DATA;const decisions=JSON.parse(localStorage.getItem('autocine-review-v1')||'{}');function card(file,label){let d=document.createElement('div');let a=document.createElement('a');a.href=file;a.target='_blank';let im=document.createElement('img');im.src=file;im.loading='lazy';let box=document.createElement('div');box.className='image';a.append(im);box.append(a);d.append(box);let text=document.createElement('small');text.textContent=label+' '+file;d.append(text);let s=document.createElement('select');for(let [v,t] of [['','未選別'],['use','使う'],['reject','使わない'],['repair','要手直し']]){let op=new Option(t,v);s.add(op)}s.value=decisions[file]||'';s.onchange=()=>{decisions[file]=s.value;localStorage.setItem('autocine-review-v1',JSON.stringify(decisions))};d.append(s);return d}for(let row of data){let art=document.createElement('article');art.dataset.search=row.number+' '+row.source;let h=document.createElement('h2');h.textContent='No.'+row.number+' '+row.source;art.append(h);let p=document.createElement('p');p.textContent='原本透過 '+row.original.length+'点 ／ 生成・再構成 '+row.generated.length+'点';art.append(p);let sec=document.createElement('section');let ref=document.createElement('div');let img=document.createElement('img');img.src=row.preview;img.loading='lazy';ref.append(img);sec.append(ref);sec.append(card(row.original[0],'原本透過'));sec.append(card(row.generated[0],'生成・再構成'));art.append(sec);for(let [label,files] of [['原本透過の全候補',row.original],['生成・再構成の全候補',row.generated]]){let det=document.createElement('details');let sum=document.createElement('summary');sum.textContent=label+' ('+files.length+')';det.append(sum);let s=document.createElement('section');det.ontoggle=()=>{if(det.open&&!s.childElementCount){for(let f of files)s.append(card(f,label))}};det.append(s);art.append(det)}document.querySelector('#list').append(art)}document.querySelector('#search').oninput=e=>{let q=e.target.value.toLowerCase();for(let a of document.querySelectorAll('article'))a.hidden=!a.dataset.search.toLowerCase().includes(q)};document.querySelector('#bg').onchange=e=>{for(let a of document.querySelectorAll('.image'))a.className='image '+e.target.value};document.querySelector('#export').onclick=()=>{let b=new Blob([JSON.stringify({schema_version:1,decisions},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='AutoCine_selection.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)};</script></html>'''
page=page.replace('DATA',json.dumps(rows,ensure_ascii=False).replace('<','\\u003c'))
fxrows=[dict(id=s['id'],label=s['label'],ornament=s['layers']['ornament'].split('kill_frames_chatgpt/')[1],motion=s['motion_preview'].split('kill_frames_chatgpt/')[1]) for s in specs]
page=page.replace('</html>','<script>const fxdata='+json.dumps(fxrows,ensure_ascii=False).replace('<','\\u003c')+''';let fxhead=document.createElement('h1');fxhead.textContent='A/B/C/D・Dテーマ演出';document.querySelector('#list').append(fxhead);for(let row of fxdata){let art=document.createElement('article');art.dataset.search=row.id+' '+row.label;let h=document.createElement('h2');h.textContent=row.id+' '+row.label;art.append(h);let sec=document.createElement('section');sec.append(card(row.ornament,'原本由来の装飾'));sec.append(card(row.motion,'演出プレビュー・設計案'));art.append(sec);document.querySelector('#list').append(art)}</script></html>''')
(ROOT/'REVIEW_SELECTION_V1.html').write_text(page,encoding='utf-8')
with (ROOT/'REVIEW_PAIR_INDEX_V1.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.writer(f);w.writerow(['number','source','original_alpha_count','generated_count','original_folder','generated_files','selection_state'])
    for row in rows:w.writerow([row['number'],row['source'],len(row['original']),len(row['generated']),f'original_alpha/review_v1/{row["number"]}/',';'.join(row['generated']),'user_pending'])
delivery=read(ROOT/'DELIVERY_REVIEW_V1.json');delivery.update(generated_source_coverage=89,generated_review_files=len(generated),selection_html='REVIEW_SELECTION_V1.html',decision_owner='user',final_approved_count=0);write(ROOT/'DELIVERY_REVIEW_V1.json',delivery)
# Preserve the pre-request tracking file rather than overwriting its historical entries.
(ROOT/'manifest.json').write_bytes(subprocess.check_output(['git','show','HEAD:'+str((ROOT/'manifest.json').relative_to(REPO)).replace('\\','/')],cwd=REPO))
print(json.dumps(dict(original_sources=89,original_part_records=len(original['assets']),generated_sources=89,generated_files=len(generated),effect_designs=len(specs))))
